import re,datetime as D
busy={}
for p in ['alice','bob','carol']:
    t=open(f'/app/{p}_calendar.ics').read()
    busy[p]=[(D.datetime.strptime(a,'%Y%m%dT%H%M%SZ'),D.datetime.strptime(b,'%Y%m%dT%H%M%SZ')) for a,b in re.findall(r'DTSTART:(\S+)\s+DTEND:(\S+)',t)]
def ok(s):
    e=s+D.timedelta(hours=1); d=s.date(); wd=s.weekday()
    m=lambda h,mi=0:D.datetime(d.year,d.month,d.day,h,mi)
    if s<m(10) or e>m(14): return False
    if wd in(1,3) and e>m(16,30): return False
    if e>m(17): return False
    if s<m(12,30) and e>m(12): return False
    for p in busy:
        for a,b in busy[p]:
            if s<b and a<e: return False
    return True
c=[]
for day in range(15,20):
    t=D.datetime(2024,1,day,9)
    while t<=D.datetime(2024,1,day,17):
        if ok(t): c.append(t)
        t+=D.timedelta(minutes=1)
print(c[:3],len(c))
EOF
./envcp /tmp/s.py :/tmp/s.py && ./envrun 'python3 /tmp/s.py'
